// Archi — სექცია 585. მხოლოდ კითხვა.
const BASE    = 'https://crm.archi.ge/rest/1/ARCHI_TOKEN/';   // <- ტოკენი
const SECTION = 585;

// Bitrix-ს PHP-სტილის ფრჩხილებიანი პარამეტრები სჭირდება: filter[SECTION_ID]=585
const qs = (obj, prefix, out) => {
  out = out || [];
  for (const [k, v] of Object.entries(obj)) {
    const key = prefix ? prefix + '[' + k + ']' : k;
    if (v === null || v === undefined) continue;
    if (Array.isArray(v)) { v.forEach((x, i) => qs({ [i]: x }, key, out)); }
    else if (typeof v === 'object') { qs(v, key, out); }
    else { out.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(v))); }
  }
  return out;
};

const bitrix = async (base, method, params) => await this.helpers.httpRequest({
  method: 'POST',
  url: base + method + '.json',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8' },
  body: qs(params).join('&'),
  json: true,
});

const fetchAll = async (base, params) => {
  const rows = [];
  let start = 0;
  for (let guard = 0; guard < 500; guard++) {
    const r = await bitrix(base, 'crm.product.list', Object.assign({}, params, { start }));
    if (r.error) throw new Error(r.error + ': ' + (r.error_description || ''));
    rows.push(...(r.result || []));
    if (r.next === undefined || r.next === null) break;
    start = r.next;
  }
  return rows;
};

const rows = await fetchAll(BASE, {
  filter: { SECTION_ID: SECTION },
  select: ['ID', 'NAME', 'PROPERTY_376', 'PROPERTY_377', 'PROPERTY_429'],
});

// Archi-ზე სტატუსი სიის ტიპისაა — REST enum ID-ს აბრუნებს, არა ტექსტს
const STATUS = {
  '810':  'გაყიდული',
  '811':  'თავისუფალი',
  '819':  'დაჯავშნილი',
  '833':  'Not In Sale',
  '1324': 'No Price',
};
const val = (p) => (p && p.value !== undefined ? p.value : null);

return rows.map((p) => ({ json: {
  წყარო: 'archi',
  archi_id: String(p.ID),
  ბინის_ნომერი: val(p.PROPERTY_377) || p.NAME || '',
  სართული: val(p.PROPERTY_376) || '',
  სტატუსი: STATUS[val(p.PROPERTY_429)] || ('უცნობი #' + val(p.PROPERTY_429)),
} }));

// Next — სექცია 28. მხოლოდ კითხვა.
const BASE    = 'https://bitrix.nextgroup.ge/rest/1/NEXT_TOKEN/';   // <- ტოკენი
const SECTION = 28;

// Bitrix-ს PHP-სტილის ფრჩხილებიანი პარამეტრები სჭირდება: filter[SECTION_ID]=585
const qs = (obj, prefix, out) => {
  out = out || [];
  for (const [k, v] of Object.entries(obj)) {
    const key = prefix ? prefix + '[' + k + ']' : k;
    if (v === null || v === undefined) continue;
    if (Array.isArray(v)) { v.forEach((x, i) => qs({ [i]: x }, key, out)); }
    else if (typeof v === 'object') { qs(v, key, out); }
    else { out.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(v))); }
  }
  return out;
};

const bitrix = async (base, method, params) => await this.helpers.httpRequest({
  method: 'POST',
  url: base + method + '.json',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8' },
  body: qs(params).join('&'),
  json: true,
});

const fetchAll = async (base, params) => {
  const rows = [];
  let start = 0;
  for (let guard = 0; guard < 500; guard++) {
    const r = await bitrix(base, 'crm.product.list', Object.assign({}, params, { start }));
    if (r.error) throw new Error(r.error + ': ' + (r.error_description || ''));
    rows.push(...(r.result || []));
    if (r.next === undefined || r.next === null) break;
    start = r.next;
  }
  return rows;
};

const rows = await fetchAll(BASE, {
  filter: { SECTION_ID: SECTION },
  select: ['ID', 'NAME', 'PROPERTY_61', 'PROPERTY_63', 'PROPERTY_64', 'PROPERTY_546'],
});

const val = (p) => (p && p.value !== undefined ? p.value : null);

return rows.map((p) => ({ json: {
  წყარო: 'next',
  archi_id: val(p.PROPERTY_546) ? String(val(p.PROPERTY_546)) : '',
  next_id: String(p.ID),
  ბინის_ნომერი: val(p.PROPERTY_63) || p.NAME || '',
  სართული: val(p.PROPERTY_61) || '',
  სტატუსი: val(p.PROPERTY_64) || '',
} }));

// Archi-ს სტატუსი -> რას უნდა შეესაბამებოდეს Next-ში.
// null = Next-ში განზრახ არ აიტვირთა, ანუ შესადარებელი არ არის.
const EXPECT = {
  'თავისუფალი':  'თავისუფალი',
  'გაყიდული':    'გაყიდული',
  'დაჯავშნილი':  'ფასიანი ჯავშანი',
  'Not In Sale': null,
  'No Price':    null,
};

const items = $input.all().map((i) => i.json);
const archi = new Map();
const next  = new Map();
for (const r of items) {
  if (r.წყარო === 'archi') archi.set(r.archi_id, r);
  else if (r.archi_id) next.set(r.archi_id, r);
  else next.set('next_only_' + r.next_id, r);
}

const out = [];

for (const [id, a] of archi) {
  const n = next.get(id);
  const expected = EXPECT[a.სტატუსი];
  let შედარდა, ემთხვევა, შედეგი;

  if (expected === null && !n) {
    შედარდა = false; ემთხვევა = null;
    შედეგი = 'არ შედარდა — Next-ში განზრახ არ არის';
  } else if (expected === null && n) {
    შედარდა = true; ემთხვევა = false;
    შედეგი = 'Archi-ში გასაყიდი არაა, Next-ში კი არის';
  } else if (!n) {
    შედარდა = true; ემთხვევა = false;
    შედეგი = 'აკლია Next-ში';
  } else {
    შედარდა = true; ემთხვევა = (n.სტატუსი === expected);
    შედეგი = ემთხვევა ? 'ემთხვევა' : 'არ ემთხვევა';
  }

  out.push({ json: {
    აიდი: id,
    Next_ID: n ? n.next_id : '—',
    ბინის_ნომერი: a.ბინის_ნომერი,
    სართული: a.სართული,
    Archi_სტატუსი: a.სტატუსი,
    Next_სტატუსი: n ? n.სტატუსი : '—',
    შედეგი: შედეგი,
    შედარდა: შედარდა,
    ემთხვევა: ემთხვევა,
  } });
}

for (const [key, n] of next) {
  if (key.indexOf('next_only_') === 0 || !archi.has(key)) {
    out.push({ json: {
      აიდი: n.archi_id || '—',
      Next_ID: n.next_id,
      ბინის_ნომერი: n.ბინის_ნომერი,
      სართული: n.სართული,
      Archi_სტატუსი: '—',
      Next_სტატუსი: n.სტატუსი,
      შედეგი: 'Archi-ში არ არის',
      შედარდა: true,
      ემთხვევა: false,
    } });
  }
}

// ჯერ პრობლემები, მერე დამთხვეული, ბოლოს შეუდარებელი
const rank = (r) => (r.json.ემთხვევა === false ? 0 : r.json.ემთხვევა === true ? 1 : 2);
out.sort((x, y) => rank(x) - rank(y)
  || String(x.json.ბინის_ნომერი).localeCompare(String(y.json.ბინის_ნომერი)));
return out;

const rows = $input.all().map((i) => i.json);

const შედარებული = rows.filter((r) => r.შედარდა);
const ok         = შედარებული.filter((r) => r.ემთხვევა === true);
const bad        = შედარებული.filter((r) => r.ემთხვევა === false);
const skip       = rows.filter((r) => !r.შედარდა);

const byResult = {};
for (const r of rows) byResult[r.შედეგი] = (byResult[r.შედეგი] || 0) + 1;

const ხაზები = bad.map((r) =>
  'ბინა ' + r.ბინის_ნომერი +
  ' (სართ. ' + r.სართული + ', ID ' + r.აიდი + ')' +
  ' : Archi = ' + r.Archi_სტატუსი +
  '  |  Next = ' + r.Next_სტატუსი +
  '  ->  ' + r.შედეგი
);

return [{ json: {
  შედარდა: შედარებული.length,
  ემთხვევა: ok.length,
  არ_ემთხვევა: bad.length,
  არ_შედარდა: skip.length,
  სულ_Archi: rows.filter((r) => r.Archi_სტატუსი !== '—').length,
  სულ_Next: rows.filter((r) => r.Next_სტატუსი !== '—').length,
  დაშლილი: byResult,
  შეუსაბამობები: bad.map((r) => ({
    აიდი: r.აიდი,
    Next_ID: r.Next_ID,
    ბინის_ნომერი: r.ბინის_ნომერი,
    სართული: r.სართული,
    Archi_სტატუსი: r.Archi_სტატუსი,
    Next_სტატუსი: r.Next_სტატუსი,
    შედეგი: r.შედეგი,
  })),
  სია_ტექსტად: bad.length ? ხაზები.join(String.fromCharCode(10)) : 'შეუსაბამობა არ არის',
  თარიღი: new Date().toISOString(),
} }];

// Archi — ჩანაწერი უნივერსალურ სიაში 228 (Archi_Next_log).
// ერთადერთი ადგილი მთელ workflow-ში, სადაც ჩაწერა ხდება.
const BASE   = 'https://crm.archi.ge/rest/1/ARCHI_TOKEN/';   // <- ტოკენი
const IBLOCK = 228;
const ჩაწერა = true;   // false -> ველებს ამზადებს, ბიტრიქსში არაფერს წერს

// ველების კოდები სიიდან 228 (წაკითხულია lists.field.get-ით)
const F = {
  დრო:         'PROPERTY_1703',   // გაშვების დრო   S:DateTime
  შედარდა:     'PROPERTY_1704',   // შედარდა        N
  ემთხვევა:    'PROPERTY_1705',   // ემთხვევა       N
  არ_ემთხვევა: 'PROPERTY_1706',   // არ ემთხვევა    N
  პრობლემაა:   'PROPERTY_1707',   // პრობლემაა      L
  არ_შედარდა:  'PROPERTY_1708',   // არ შედარდა     N
  სულ_Archi:   'PROPERTY_1709',   // სულ Archi      N
  სულ_Next:    'PROPERTY_1710',   // სულ Next       N
  სია:         'DETAIL_TEXT',     // შეუსაბამობების სია
};
const კი = 2489, არა = 2490;   // PROPERTY_1707-ის მნიშვნელობები

const qs = (obj, prefix, out) => {
  out = out || [];
  for (const [k, v] of Object.entries(obj)) {
    const key = prefix ? prefix + '[' + k + ']' : k;
    if (v === null || v === undefined) continue;
    if (Array.isArray(v)) { v.forEach((x, i) => qs({ [i]: x }, key, out)); }
    else if (typeof v === 'object') { qs(v, key, out); }
    else { out.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(v))); }
  }
  return out;
};

const s = $input.first().json;

// ბიტრიქსის თარიღის ფორმატი: DD.MM.YYYY HH:MM:SS
const d  = new Date();
const p2 = (n) => String(n).padStart(2, '0');
const თარიღი = p2(d.getDate()) + '.' + p2(d.getMonth() + 1) + '.' + d.getFullYear();
const დრო    = p2(d.getHours()) + ':' + p2(d.getMinutes()) + ':' + p2(d.getSeconds());

const NLC = String.fromCharCode(10);
const სია = s.არ_ემთხვევა > 0
  ? s.სია_ტექსტად
  : 'შეუსაბამობა არ არის' + NLC + NLC + 'დაშლილი: ' + JSON.stringify(s.დაშლილი);

const fields = {};
fields['NAME']        = 'შედარება ' + თარიღი + ' ' + დრო;
fields[F.დრო]         = თარიღი + ' ' + დრო;
fields[F.შედარდა]     = s.შედარდა;
fields[F.ემთხვევა]    = s.ემთხვევა;
fields[F.არ_ემთხვევა] = s.არ_ემთხვევა;
fields[F.არ_შედარდა]  = s.არ_შედარდა;
fields[F.სულ_Archi]   = s.სულ_Archi;
fields[F.სულ_Next]    = s.სულ_Next;
fields[F.პრობლემაა]   = s.არ_ემთხვევა > 0 ? კი : არა;
fields[F.სია]         = სია;

if (!ჩაწერა) {
  return [{ json: { რეჟიმი: 'სატესტო — ბიტრიქსში არაფერი ჩაწერილა', fields } }];
}

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: BASE + 'lists.element.add.json',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8' },
  body: qs({
    IBLOCK_TYPE_ID: 'lists',
    IBLOCK_ID: IBLOCK,
    ELEMENT_CODE: 'cmp-' + d.getTime(),
    FIELDS: fields,
  }).join('&'),
  json: true,
});

if (res.error) throw new Error('lists.element.add: ' + res.error + ' — ' + (res.error_description || ''));

return [{ json: {
  ჩაიწერა: true,
  ელემენტის_ID: res.result,
  სათაური: fields['NAME'],
  შედარდა: s.შედარდა,
  ემთხვევა: s.ემთხვევა,
  არ_ემთხვევა: s.არ_ემთხვევა,
  პრობლემაა: s.არ_ემთხვევა > 0 ? 'კი' : 'არა',
} }];
